using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
using Ability=Polytopia.Data.UnitAbility.Type;
using Improvement=Polytopia.Data.ImprovementData.Type;
namespace Deception.Tests
{
 public static partial class RogueTests
 {
  static int Assertions;static readonly List<string> Cases=new();
  static void Check(bool yes,string why){Assertions++;if(!yes)throw new Exception(why);}
  static void Test(string name,Action action){try{NativeRogueRules.Clear();NativeFeignSupportEffects.Clear();NativeGameStateEnvelope.Values.Clear();NativeRegroupSession.Owned.Clear();NativeRegroupSession.Faults.Clear();Fault.At="";action();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
  static LedgerAppearance Mask()=>new("warrior",new("imperius","default"),new("imperius","default"),new("imperius","default"),7,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
  static TileData Tile(GameState s,int x,int y)=>MapDataExtensions.GetTile(s.Map,new(x,y))!;
  static UnitState Unit(GameState s,uint id)=>s.Map.Tiles.Values.Select(t=>t.unit).Single(u=>u?.id==id)!;
  static NativeIdentityLedger Read(GameState s){var v=NativeGameStateEnvelope.Get(s)!;return NativeIdentityLedgerCodec.Decode(v.Bytes(),v.Revision);}
  static void Write(GameState s,NativeIdentityLedger ledger)=>NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(ledger,0));
  static GameState Make(bool rogue=true)
  {
   var s=new GameState();s.Map.Tiles.Values=(from y in Enumerable.Range(0,5)from x in Enumerable.Range(0,6)select new TileData{coordinates=new(x,y)}).ToArray();
   foreach(byte p in new byte[]{1,2,3}){s.PlayerStates.Add(new(){Id=p});foreach(var t in s.Map.Tiles.Values)t.explorers.Add(p);}
   Tile(s,0,0).unit=new(){id=1,owner=1,coordinates=new(0,0),home=new(0,0)};
   Tile(s,1,2).unit=new(){id=2,owner=rogue?(byte)1:(byte)2,coordinates=new(1,2),home=new(5,4),moved=true,attacked=true};
   Tile(s,5,4).unit=new(){id=3,owner=3,coordinates=new(5,4),home=new(5,4)};
   var rows=s.Map.Tiles.Values.Where(t=>t.unit is not null).Select(t=>new LedgerUnit(t.unit!.id,t.unit.id,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,3,Rogue:rogue&&t.unit.id==2?new(2,1,4):null,Acquisitions:rogue&&t.unit.id==2?new[]{new LedgerAcquisition(1,4)}:null)).OrderBy(x=>x.LogicalId).ToArray();
   Write(s,new(Guid.Parse("dfd64288-4b90-4c6f-a896-e529f2ca7ff4"),100,1,rows,Array.Empty<LedgerReceipt>()));NativeRegroupSession.Owned.Add(s);return s;
  }
  static int Count(GameState s,byte p){s.TryGetPlayer(p,out var player);int n=0;if(NativeRogueAccounting.Count(player!,s,ref n))n=PlayerExtensions.CountUnits(player!,s);return n;}
  static void Death(GameState s,TileData t){NativeRogueAccounting.BeforeDeath(s,t,out var old);Exception? error=null;try{ActionUtils.KillUnit(s,t);}catch(Exception e){error=e;throw;}finally{NativeRogueAccounting.OwnersFinished(error,old);}}
  static int Defence(GameState s,UnitState u){NativeRogueAccounting.BeforeDefence(u,s,out var scope);try{return UnitDataExtensions.GetDefenceBonus(u,s);}finally{NativeRogueAccounting.DefenceFinished(null,scope);}}
  static object Positions(params (int X,int Y)[] ps)=>Native.NewList("WorldCoordinates",ps.Select(p=>(object)new WorldCoordinates(p.X,p.Y)));
  static string World(GameState s)=>string.Join("|",s.Map.Tiles.Values.Select(t=>$"{t.coordinates.X},{t.coordinates.Y}:{t.owner}/{t.unit?.id}:{t.unit?.owner}:{t.unit?.health}:{t.unit?.moved}:{t.unit?.attacked}:{t.improvement?.Wall}:{string.Join(',',Native.Items(t.explorers))}"));
  public static int Run(){try{
   Test("registration-safe-accounting-rules-tactics-hooks",()=>{var h=new HarmonyLib.Harmony();NativeRogueAccounting.Install(h);NativeRogueRules.Install(h);NativeRogueTactics.Install(h);Check(h.Hooks.Count==25,"seven accounting, sixteen rules, two safe tactics detours");Check(!h.Hooks.Any(x=>x.Contains("IsAllowedToFinish")),"unsafe wrapped PathFinderSettings not installed");});
   Test("permanent-counts-reserve-original-owner-and-exclude-commander",()=>{var s=Make();string before=World(s);Check(Count(s,1)==1&&Count(s,2)==1&&Count(s,3)==1,"one root belongs to each permanent owner");Check(before==World(s),"count does not edit native owner fields");});
   Test("count-out-list-uses-identical-permanent-roster",()=>{var s=Make();s.TryGetPlayer(2,out var p);object list=Native.NewList("UnitState",Array.Empty<object>());int n=0;Check(!NativeRogueAccounting.CountList(p!,s,ref list,ref n),"custom count handles Rogue context");Check(n==1&&Native.Same(Native.Items(list).Single(),Unit(s,2)),"out list contains exact reserved physical unit");});
   Test("ordinary-count-query-remains-native",()=>{var s=Make(false);int n=77;object list=new object(),old=list;s.TryGetPlayer(1,out var p);Check(NativeRogueAccounting.Count(p!,s,ref n)&&n==77,"no Rogue leaves native result");Check(NativeRogueAccounting.CountList(p!,s,ref list,ref n)&&ReferenceEquals(old,list),"native out parameter remains untouched");});
   Test("home-support-retains-slot-during-borrow-return-and-cargo",()=>{var s=Make();var u=Unit(s,2);u.passengerUnit=new(){id=9,owner=1,home=u.home};Check(MapDataExtensions.GetCityUnitCount(s.Map,new(5,4))==2,"native home count includes borrowed root exactly once, cargo not separate");NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(MapDataExtensions.GetCityUnitCount(s.Map,new(5,4))==2&&u.home.X==5&&u.home.Y==4,"return does not move or duplicate home reservation");});
   Test("elimination-count-retains-last-borrowed-unit",()=>{var s=Make();Check(Count(s,2)>0,"permanent owner with only a Rogue is not unitless");Death(s,Tile(s,1,2));Check(Count(s,2)==0,"actual death releases final reservation even before ledger reconciliation");});
   Test("dead-and-foreign-rows-do-not-invent-physical-roster",()=>{var s=Make();Tile(s,1,2).unit=null;Check(Count(s,2)==0,"missing root is not resurrected by living stale row");Write(s,Read(s) with{Units=Read(s).Units.Select(r=>r.NativeId==2?r with{Alive=false,Rogue=null}:r).ToArray()});Check(Count(s,2)==0,"retired identity remains absent");});
   Test("death-score-debits-permanent-owner-without-changing-killer",()=>{var s=Make();var u=Unit(s,2);u.passengerUnit=new(){id=9,owner=1};Death(s,Tile(s,1,2));Check(Native.Items(s.ActionStack).OfType<DecreaseScoreAction>().Single().PlayerId==2,"native score action captures remembered owner");Check(u.owner==1&&u.passengerUnit.owner==1&&Unit(s,1).owner==1,"temporary corpse/cargo substitutions restored, killer untouched");});
   Test("death-scope-finalizer-restores-error-and-nesting",()=>{var s=Make();var u=Unit(s,2);u.passengerUnit=new(){id=9,owner=3};NativeRogueAccounting.BeforeDeath(s,Tile(s,1,2),out var outer);Check(u.owner==2&&u.passengerUnit.owner==2,"native death sees permanent root/cargo");NativeRogueAccounting.BeforeDeath(s,Tile(s,1,2),out var inner);var e=new Exception("native failure");Check(ReferenceEquals(e,NativeRogueAccounting.OwnersFinished(e,inner))&&u.owner==2,"nested unwind returns outer context");NativeRogueAccounting.OwnersFinished(e,outer);Check(u.owner==1&&u.passengerUnit.owner==3,"exact original fields restored on failure");});
   Test("confirmed-wipe-includes-reserved-rogue",()=>{var s=Make();NativeRogueAccounting.BeforeWipe(s,out var scope);new WipePlayerAction{PlayerId=2}.Execute(s);NativeRogueAccounting.OwnersFinished(null,scope);var removals=Native.Items(s.ActionStack).OfType<DisbandUnitAction>().ToArray();Check(removals.Length==1&&removals[0].Target.X==1&&removals[0].Target.Y==2,"native forced-removal queues remembered owner's body");Death(s,Tile(s,1,2));NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(Tile(s,1,2).unit is null&&Count(s,2)==0,"confirmed removed body never returns");});
   Test("commander-wipe-excludes-foreign-borrowed-unit",()=>{var s=Make();NativeRogueAccounting.BeforeWipe(s,out var scope);new WipePlayerAction{PlayerId=1}.Execute(s);NativeRogueAccounting.OwnersFinished(null,scope);var removals=Native.Items(s.ActionStack).OfType<DisbandUnitAction>().ToArray();Check(removals.Length==1&&removals[0].Target.X==0,"commander defeat removes only permanently owned body");Check(Unit(s,2).owner==1,"command field restored until pending return");});
   Test("wipe-error-restores-all-rogues-and-ledger",()=>{var s=Make();var original=NativeGameStateEnvelope.Get(s);var before=World(s);NativeRogueAccounting.BeforeWipe(s,out var scope);var e=new Exception("wipe");Check(ReferenceEquals(e,NativeRogueAccounting.OwnersFinished(e,scope)),"native error propagates");Check(before==World(s)&&ReferenceEquals(original,NativeGameStateEnvelope.Get(s)),"no owner or ledger mutation escapes failing scope");});
   foreach(byte cityOwner in new byte[]{1,2,3})Test("rogue-fortify-denied-city-owner-"+cityOwner,()=>{var s=Make();var u=Unit(s,2);u.Abilities.Add(Ability.Fortify);var t=Tile(s,1,2);t.owner=cityOwner;t.improvement=new(){Wall=true};string before=World(s);Check(Defence(s,u)==10,"Rogue gains no ownership-only wall bonus");Check(before==World(s)&&t.HasImprovement(Improvement.City),"world and city predicate restored");});
   Test("terrain-and-poison-native-defence-survive-city-veto",()=>{var s=Make();var u=Unit(s,2);u.Abilities.Add(Ability.Fortify);var t=Tile(s,1,2);t.owner=1;t.improvement=new(){Wall=true};t.terrain=4;s.TryGetPlayer(1,out var p);p!.TerrainDefence=true;Check(Defence(s,u)==15,"commander terrain technology retained");u.effects.Add(UnitEffect.Poisoned);Check(Defence(s,u)==7,"native poison adjustment applies to retained terrain");});
   Test("ordinary-own-city-fortification-remains-native",()=>{var s=Make(false);var u=Unit(s,2);u.Abilities.Add(Ability.Fortify);Tile(s,1,2).owner=2;Tile(s,1,2).improvement=new(){Wall=true};Check(Defence(s,u)==40,"normal fortified owner receives native walls");});
   Test("fortification-scope-exact-tile-kind-error-and-nesting",()=>{var s=Make();var t=Tile(s,1,2);t.improvement=new();var other=Tile(s,0,0);other.improvement=new();NativeRogueAccounting.BeforeDefence(Unit(s,2),s,out var scope);bool result=true;Check(NativeRogueAccounting.CityFortification(t,Improvement.Farm,ref result)&&result,"unrelated improvements untouched");Check(other.HasImprovement(Improvement.City)&&!t.HasImprovement(Improvement.City),"only exact query tile is suppressed");NativeRogueAccounting.BeforeDefence(Unit(s,2),s,out var inner);NativeRogueAccounting.DefenceFinished(null,inner);Check(!t.HasImprovement(Improvement.City),"nested unwind retains outer scope");var e=new Exception();Check(ReferenceEquals(e,NativeRogueAccounting.DefenceFinished(e,scope))&&t.HasImprovement(Improvement.City),"error restores native city query");});
   Test("current-commander-guard-and-expired-order-denial",()=>{var s=Make();var u=Unit(s,2);Check(NativeRogueRules.CanCommand(s,u,1)&&!NativeRogueRules.CanCommand(s,u,2),"current actor owns only command privilege");s.CurrentTurn++;Check(!NativeRogueRules.CanCommand(s,u,1),"same actor later turn is not prior allowance");s.CurrentPlayer=3;Check(!NativeRogueRules.CanCommand(s,u,1),"out-of-turn actor denied");});
   Test("return-at-owner-turn-clears-flags-and-cargo-once",()=>{var s=Make();var u=Unit(s,2);u.passengerUnit=new(){id=9,owner=1,moved=true,attacked=true};u.effects.Add(UnitEffect.Frozen);u.passengerUnit.effects.Add(UnitEffect.Poisoned);var effects=u.effects;NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=3},s);Check(u.owner==1&&u.attacked,"unrelated turn does not return");NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(u.owner==2&&u.passengerUnit.owner==2&&!u.moved&&!u.attacked&&!u.passengerUnit.moved&&!u.passengerUnit.attacked,"owner receives one refreshed physical allowance");Check(ReferenceEquals(effects,u.effects)&&u.HasEffect(UnitEffect.Frozen)&&u.passengerUnit.HasEffect(UnitEffect.Poisoned),"no invented status tick on return");Check(Read(s).Units.Single(x=>x.NativeId==2).Rogue is null&&Read(s).Units.Single(x=>x.NativeId==2).Acquisitions!.Length==1,"return removed while acquisition history preserved");u.attacked=true;NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(u.attacked,"second callback cannot refresh twice");});
   Test("return-under-blackout-does-not-reveal",()=>{var s=Make();Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(2,1,2)}});var tile=Tile(s,1,2);tile.explorers.Remove(2);NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(Unit(s,2).owner==2&&!NativeSpyNetwork.Accessible(s,tile,2)&&!tile.GetExplored(2),"return remains fogged and inaccessible");});
   foreach(bool failed in new[]{false,true})Test("end-turn-restores-temporary-owner-"+(failed?"error":"success"),()=>{var s=Make();var u=Unit(s,2);u.passengerUnit=new(){id=9,owner=1};var before=World(s);NativeRogueRules.BeforeEnd(s,out var scope);Check(u.owner==2&&u.passengerUnit.owner==2,"native turn effects use remembered schedule");var error=failed?new Exception("native"):null;Check(ReferenceEquals(error,NativeRogueRules.EndFinished(error,scope)),"native error identity retained");Check(before==World(s)&&u.passengerUnit.owner==1,"owners restored before returning to caller");});
   foreach(bool failed in new[]{false,true})Test("end-turn-effect-flush-"+(failed?"cancels-on-error":"after-owner-restore"),()=>{var s=Make();Write(s,Read(s) with{Units=Read(s).Units.Select(r=>r.NativeId==2?r with{Independent=true,Appearance=Mask() with{Effects=new[]{"Boosted"}}}:r).ToArray()});var u=Unit(s,2);u.effects.Add(UnitEffect.Boosted);NativeRogueRules.BeforeEnd(s,out var scope);u.RemoveEffect(UnitEffect.Boosted);Check(Read(s).Units.Single(r=>r.NativeId==2).Appearance!.Effects.Contains("Boosted"),"apparent event queued until boundary");NativeRogueRules.EndFinished(failed?new Exception():null,scope);Check(u.owner==1,"command owner restored before flush");Check(Read(s).Units.Single(r=>r.NativeId==2).Appearance!.Effects.Contains("Boosted")==failed,"successful turn applies once; exception cancels apparent event");NativeFeignSupportEffects.Flush(s);Check(Read(s).Units.Single(r=>r.NativeId==2).Appearance!.Effects.Contains("Boosted")==failed,"repeat flush is no-op");});
   foreach(string action in new[]{"command","attack","infiltrate"})Test("queued-rogue-diplomacy-scope-"+action,()=>{var s=Make();ActionBase a=action switch{"command"=>new AttackCommand(),"attack"=>new AttackAction(),_=>new InfiltrateAction()};a.Origin=new(1,2);a.Target=new(0,0);if(a is AttackCommand c)c.UnitId=2;else s.ActionStack.Add(a);Check(NativeRogueRules.Diplomacy(),"ordinary diplomacy initially enabled");NativeRogueRules.BeforeAttack(a,s,out var scope);Check(!NativeRogueRules.Diplomacy(),"real queued source suppresses treaty updates");NativeRogueRules.BeforeAttack(a,s,out var inner);NativeRogueRules.AttackFinished(null,inner);Check(!NativeRogueRules.Diplomacy(),"nested scope does not leak early");var error=new Exception();Check(ReferenceEquals(error,NativeRogueRules.AttackFinished(error,scope))&&NativeRogueRules.Diplomacy(),"error restores ordinary diplomacy");});
   Test("ordinary-action-keeps-treaty-processing",()=>{var s=Make();NativeRogueRules.BeforeAttack(new AttackAction{Origin=new(0,0)},s,out var scope);Check(NativeRogueRules.Diplomacy(),"ordinary attacker receives no deniability");NativeRogueRules.AttackFinished(null,scope);});
   Test("rogue-bans-capture-ruins-disband-but-sieges-owned-cities",()=>{var s=Make();bool allowed=true;Check(!NativeRogueRules.Ban(Unit(s,2),s,ref allowed)&&!allowed,"Rogue cannot use banned real actions");var t=Tile(s,1,2);t.owner=1;bool siege=false;NativeRogueRules.Siege(t,s,ref siege);int work=4;NativeRogueRules.Work(t,s,ref work);Check(siege&&work==0,"Rogue interrupts own-command city income too");});
   Test("permanent-conversion-preserves-action-and-clears-return",()=>{var s=Make();var u=Unit(s,2);NativeRogueRules.BeforeConvert(new ConvertAction{Target=u.coordinates},s,out var scope);Check(u.owner==2,"native conversion debits original owner");u.owner=3;u.moved=u.attacked=false;NativeRogueRules.AfterConvert(s,scope);NativeRogueRules.ConvertFinished(null,scope);Check(u.owner==3&&u.moved&&u.attacked&&!NativeRogueRules.IsRogue(s,u),"conversion retains native new owner and spent allowance");NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(u.owner==3,"converted body never returns");});
   Test("conversion-error-restores-command-context-and-faults",()=>{var s=Make();var u=Unit(s,2);NativeRogueRules.BeforeConvert(new ConvertAction{Target=u.coordinates},s,out var scope);var e=new Exception();Check(ReferenceEquals(e,NativeRogueRules.ConvertFinished(e,scope))&&u.owner==1,"failed native conversion restores prior commander");Check(NativeRegroupSession.Faults.Count==1&&NativeRogueRules.IsRogue(s,u),"failed transition cannot silently erase return");});
   Test("tactical-zoc-allows-entry-denies-passing",()=>{var s=Make();var u=Unit(s,1);string before=World(s);Check(NativeRogueTactics.Allowed(s,u,u.coordinates,Positions((1,1),(0,0))),"entry into Rogue zone is permitted");Check(!NativeRogueTactics.Allowed(s,u,u.coordinates,Positions((2,1),(1,1),(0,0))),"cannot continue past intermediate controlled tile");Check(before==World(s),"path query is read-only");});
   Test("tactical-zoc-forward-and-reverse-native-paths-equivalent",()=>{var s=Make();var u=Unit(s,1);Check(!NativeRogueTactics.Allowed(s,u,u.coordinates,Positions((0,0),(1,1),(2,1)))&&!NativeRogueTactics.Allowed(s,u,u.coordinates,Positions((2,1),(1,1),(0,0))),"both native route orderings deny passage");});
   Test("tactical-zoc-real-sneak-bypasses",()=>{var s=Make();var u=Unit(s,1);u.Abilities.Add(Ability.Sneak);object path=Positions((2,1),(1,1),(0,0)),original=path;NativeRogueTactics.Path(s,u.coordinates,u,ref path);Check(ReferenceEquals(original,path)&&Native.Items(path).Count()==3,"actual Sneak retains original path list");});
   foreach(string hidden in new[]{"fog","invisible","blackout"})Test("tactical-zoc-no-hidden-authenticity-probe-"+hidden,()=>{var s=Make();var u=Unit(s,1);var t=Tile(s,1,2);if(hidden=="fog")t.explorers.Remove(1);if(hidden=="invisible")t.unit!.effects.Add(UnitEffect.Invisible);if(hidden=="blackout")Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(1,1,2)}});object path=Positions((2,1),(1,1),(0,0)),old=path;NativeRogueTactics.Path(s,u.coordinates,u,ref path);Check(ReferenceEquals(path,old),"unavailable hidden Rogue does not prune route");});
   Test("tactical-zoc-rogue-treats-commander-ordinary-unit-as-nonfriendly",()=>{var s=Make();var u=Unit(s,2);Tile(s,0,0).unit!.coordinates=new(2,1);Tile(s,2,1).unit=Tile(s,0,0).unit;Tile(s,0,0).unit=null;Check(!NativeRogueTactics.Allowed(s,u,u.coordinates,Positions((3,2),(2,2),(1,2))),"Rogue cannot pass adjacent commander unit");});
   Test("tactical-options-filtered-without-changing-world-or-input",()=>{var s=Make();var u=Unit(s,1);var before=World(s);object options=Positions((1,1),(2,2),(0,0)),original=options;NativeRogueTactics.Options(s,u.coordinates,3,u,ref options);Check(Native.Items(options).Count()==2&&Native.Items(original).Count()==3&&!ReferenceEquals(options,original),"only denied continuation removed from detached list");Check(World(s)==before,"move-option query does not mutate owner, status, map or sight");});
   foreach(UnitType form in new[]{UnitType.dcp_spy,UnitType.dcp_mimic_form_warrior,UnitType.mooni})Test("attackless-rogue-targets-not-invented-"+form,()=>{var s=Make();var u=Unit(s,2);u.type=form;u.UnitData.attack=0;object result=Positions(),before=result;NativeRogueRules.AttackOptions(s,1,u.coordinates,3,u,ref result);Check(ReferenceEquals(result,before)&&!Native.Items(result).Any(),"no weapon targets granted to attackless actual body");});
   Test("genuine-mindbender-can-target-commanded-rogue",()=>{var s=Make();var u=Unit(s,1);u.type=UnitType.mindbender;u.UnitData.attack=0;u.Abilities.Add(Ability.Convert);object result=Positions();NativeRogueRules.AttackOptions(s,1,u.coordinates,3,u,ref result);Check(Native.Items(result).Cast<WorldCoordinates>().Any(p=>p.X==1&&p.Y==2),"real converter may target same-commander Rogue without an attack weapon");});
   Test("genuine-rogue-cloak-keeps-infiltrate-own-city-target",()=>{var s=Make();var u=Unit(s,2);u.type=UnitType.cloak;u.UnitData.attack=0;u.Abilities.Add(Ability.Infiltrate);var city=Tile(s,2,2);city.owner=1;city.improvement=new();object result=Positions();NativeRogueRules.AttackOptions(s,1,u.coordinates,1,u,ref result);Check(Native.Items(result).Cast<WorldCoordinates>().Any(p=>p.X==2&&p.Y==2),"real Cloak can target commander city without damaging attack");});
   InvestmentCases();
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Actual Rogue accounting/rules/tactics and status boundary callbacks; native method ports and helper boundaries explicit; no native gameplay"}));return 0;
  }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
